# ============================================================
# SKILL ANALYSIS
# ============================================================

def skill_analysis():

    st.markdown(
        '<div class="section-title">Skill Gap Analysis</div>',
        unsafe_allow_html=True
    )

    st.markdown(
        '<div class="section-sub">'
        'Tell us what you know and we will show you what to learn next.'
        '</div>',
        unsafe_allow_html=True
    )

    st.markdown('<div class="panel">', unsafe_allow_html=True)

    c1, c2 = st.columns(2)

    with c1:
        skill_text = st.text_input(
            "YOUR CURRENT SKILLS",
            value=", ".join(st.session_state.skills),
            placeholder="Python, SQL, Excel..."
        )

    with c2:
        role = st.selectbox(
            "TARGET JOB ROLE",
            list(roles.keys()),
            index=list(roles.keys()).index(st.session_state.target_role)
        )

    st.markdown("</div>", unsafe_allow_html=True)
    st.write("")

    if st.button(
        "✦ Analyze My Skill Gap",
        type="primary",
        use_container_width=True
    ):
        current = [
            x.strip()
            for x in skill_text.split(",")
            if x.strip()
        ]

        required = roles[role]

        matched = [
            skill
            for skill in required
            if skill.lower() in [x.lower() for x in current]
        ]

        missing = [
            skill
            for skill in required
            if skill.lower() not in [x.lower() for x in current]
        ]

        score = round(len(matched) / len(required) * 100)

        st.session_state.skills = current
        st.session_state.target_role = role
        st.session_state.matched = matched
        st.session_state.missing = missing
        st.session_state.score = score
        st.session_state.analysis_done = True

    if st.session_state.analysis_done:

        st.markdown(
            '<div class="section-title">Your Analysis</div>',
            unsafe_allow_html=True
        )

        a, b, c = st.columns(3)

        with a:
            st.markdown(f"""
            <div class="analysis-score">
                <div class="analysis-label">CAREER MATCH</div>
                <div class="analysis-number">{st.session_state.score}%</div>
                <div class="analysis-label">Overall readiness</div>
            </div>
            """, unsafe_allow_html=True)

        with b:
            st.markdown(f"""
            <div class="metric-card">
                <div class="metric-icon">✓</div>
                <div class="metric-label">MATCHED SKILLS</div>
                <div class="metric-value">{len(st.session_state.matched)}</div>
                <div class="metric-desc">Skills you already have</div>
            </div>
            """, unsafe_allow_html=True)

        with c:
            st.markdown(f"""
            <div class="metric-card">
                <div class="metric-icon">!</div>
                <div class="metric-label">SKILL GAPS</div>
                <div class="metric-value">{len(st.session_state.missing)}</div>
                <div class="metric-desc">Skills to learn</div>
            </div>
            """, unsafe_allow_html=True)

        left, right = st.columns(2)

        with left:
            st.markdown(
                '<div class="section-title">✓ Matched Skills</div>',
                unsafe_allow_html=True
            )

            for skill in st.session_state.matched:
                st.markdown(
                    f'<span class="skill-pill">✓ {skill}</span>',
                    unsafe_allow_html=True
                )

        with right:
            st.markdown(
                '<div class="section-title">○ Skills to Learn</div>',
                unsafe_allow_html=True
            )

            for skill in st.session_state.missing:
                st.markdown(
                    f'<span class="skill-pill missing-pill">○ {skill}</span>',
                    unsafe_allow_html=True
                )

        st.write("")

        if st.button(
            "Build My Learning Path  →",
            type="primary",
            use_container_width=True
        ):
            st.session_state.page = "Learning Path"
            st.rerun()


# ============================================================
# LEARNING PATH
# ============================================================

def learning_path():

    st.markdown(
        '<div class="section-title">Personalized Learning Path</div>',
        unsafe_allow_html=True
    )

    st.markdown(
        '<div class="section-sub">'
        f'A practical roadmap for becoming a '
        f'<b>{st.session_state.target_role}</b>.'
        '</div>',
        unsafe_allow_html=True
    )

    current = [x.lower() for x in st.session_state.skills]

    required = roles[st.session_state.target_role]

    missing = [
        x for x in required
        if x.lower() not in current
    ]

    if not missing:
        missing = required

    total_days = 0

    st.markdown('<div class="learning-wrap">', unsafe_allow_html=True)

    for index, skill in enumerate(missing, 1):

        days, description = learning_info.get(
            skill,
            ("10 days", "Build practical knowledge through projects.")
        )

        try:
            total_days += int(days.split()[0])
        except Exception:
            total_days += 10

        st.markdown(f"""
        <div class="learning-card">
            <div style="display:flex;align-items:center;gap:17px;">
                <div class="learning-number">{index:02d}</div>
                <div style="flex:1;">
                    <div class="learning-title">{skill}</div>
                    <div class="learning-desc">{description}</div>
                </div>
                <div class="day-badge">{days}</div>
            </div>
        </div>
        """, unsafe_allow_html=True)

    st.markdown('</div>', unsafe_allow_html=True)

    st.markdown(f"""
    <div class="hero" style="padding:27px 31px;margin-top:22px;">
        <div class="hero-label">YOUR ROADMAP</div>
        <div class="hero-title" style="font-size:27px;">
            {len(missing)} skills • {total_days} days
        </div>
        <div class="hero-text">
            Learn consistently, build projects and move closer
            to your target role.
        </div>
    </div>
    """, unsafe_allow_html=True)


